import { createSyncOnceRunner, forEach, noop } from "@alova/shared";
import { createEffect, createMemo, createSignal, on, onCleanup, onMount } from "solid-js";
//#region src/statesHook/solid.ts
var solid_default = {
	name: "Solid",
	create: (data) => createSignal(data),
	export: (state) => state[0],
	dehydrate: (state) => state[0](),
	update: (newVal, state) => {
		state[1](newVal);
	},
	effectRequest: ({ handler, immediate, watchingStates = [] }) => {
		immediate && handler();
		forEach(watchingStates, (state, i) => {
			createEffect(on(state, () => {
				handler(i);
			}, { defer: true }));
		});
	},
	computed: (getter) => [createMemo(getter), noop],
	watch: (states, callback) => {
		const curStates = Array.isArray(states) ? states : [states];
		const syncRunner = createSyncOnceRunner();
		createEffect(on(curStates.map((state) => state), () => syncRunner(() => {
			callback();
		}), { defer: true }));
	},
	onMounted: (callback) => {
		onMount(callback);
	},
	onUnmounted: (callback) => {
		onCleanup(callback);
	}
};
//#endregion
export { solid_default as default };
